window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8358d787393ba9ca"]={"versions": [{"id": "FIG-8358d787393ba9ca", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur ECU-Konfiguration (AUTOSAR Parameter Configuration Schema, EcucParamConfContainerDef) des Betriebssystems (AUTOSAR_SWS_OS). Das Diagramm spezifiziert die Metamodellstruktur für <code>OsScheduleTable</code> inklusive Sub-Containern, Referenzen und Konfigurationsparametern für Ablaufpläne auf Counter-Basis innerhalb der Classic Platform. Im oberen Bildbereich ist eine Übersichtstabelle zu den enthaltenen Containern und deren Gültigkeitsbereich (<code>scope: local</code>) vorangestellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist der Container <code>OsScheduleTable</code> (Multiplizität 0..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter von <code>OsScheduleTable</code>:</p>\n<ul class=\"fig-list\">\n<li><code>OsScheduleTableRepeating</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>OsScheduleTableDuration</code>: <code>EcucIntegerParamDef</code></li>\n</ul>\n<p class=\"fig-p\">Enthaltene Referenzen von <code>OsScheduleTable</code>:</p>\n<ul class=\"fig-list\">\n<li><code>OsScheduleTableCounterRef</code>: <code>EcucReferenceDef</code>, referenziert Zielcontainer <code>OsCounter</code> (0..*).</li>\n</ul>\n<p class=\"fig-p\">Enthaltene Sub-Container (<code>+subContainer</code>) von <code>OsScheduleTable</code>:</p>\n<ul class=\"fig-list\">\n<li><code>OsScheduleTableExpiryPoint</code> (Multiplizität 1..*): Definiert Ablaufzeitpunkte.</li>\n<li>Parameter: <code>OsScheduleTblExpPointOffset</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>).</li>\n<li>Sub-Container <code>OsScheduleTableTaskActivation</code> (0..*): Aktivierung von Tasks.</li>\n<li>Sub-Container <code>OsScheduleTableEventSetting</code> (0..*): Setzen von Events; enthält Referenz <code>OsScheduleTableSetEventRef</code> zu <code>OsEvent</code>.</li>\n<li>Sub-Container <code>OsScheduleTblAdjustableExpPoint</code> (0..1): Parameter <code>OsScheduleTableMaxShorten</code> (<code>min = 0</code>) und <code>OsScheduleTableMaxLengthen</code> (<code>min = 0</code>).</li>\n<li><code>OsScheduleTableAutostart</code> (Multiplizität 0..1): Startverhalten beim OS-Hochlauf.</li>\n<li>Parameter: <code>OsScheduleTableStartValue</code> (<code>EcucIntegerParamDef</code>, 0..1).</li>\n<li>Parameter: <code>OsScheduleTableAutostartType</code> (<code>EcucEnumerationParamDef</code>).</li>\n<li>Referenz: <code>OsScheduleTableAppModeRef</code> (<code>EcucReferenceDef</code>, 1..*), verweist auf Zielcontainer <code>OsAppMode</code>.</li>\n<li><code>OsScheduleTableSync</code> (Multiplizität 0..1): Synchronisationseinstellungen.</li>\n<li>Parameter: <code>OsScheduleTblSyncStrategy</code> (<code>EcucEnumerationParamDef</code>, <code>defaultValue = NONE</code>), Literale <code>NONE</code>, <code>IMPLICIT</code>, <code>EXPLICIT</code>.</li>\n<li>Parameter: <code>OsScheduleTblExplicitPrecision</code> (<code>EcucIntegerParamDef</code>, 0..1, <code>min = 0</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Konfigurations- und Datenstruktur dar; es enthält keine dynamischen Sequenzabläufe, Verhaltensdiagramme oder Zustandsübergänge. Die funktionale Semantik umfasst das zyklische oder einmalige Durchlaufen der Ablaufzeitpunkte (<code>OsScheduleTableExpiryPoint</code>) synchron zu einem <code>OsCounter</code>, das automatische Starten bei Systemstart abhängig von <code>OsAppMode</code> und Startwert sowie optionale Synchronisationsanpassungen über definierte Minimal- und Maximaloffsets (<code>OsScheduleTblAdjustableExpPoint</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Konfigurationswerkzeuge (BSW-Generatoren) und OS-Implementierungen gemäß AUTOSAR OS-Spezifikation. Ein <code>OsScheduleTable</code> benötigt zwingend eine gültige Counter-Referenz sowie mindestens einen Expiry-Point (<code>upperMultiplicity = *</code>, <code>lowerMultiplicity = 1</code>). Die Konfiguration von Synchronisation und Autostart ist jeweils optional (0..1), erfordert bei Vorhandensein jedoch die Einhaltung der Minimalwerte (<code>min = 0</code>) und Referenzen (z. B. mindestens ein AppMode für den Autostart).</p>"}, {"id": "FIG-678078bf25c4870b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur ECU-Konfiguration (AUTOSAR Parameter Configuration Schema, EcucParamConfContainerDef) des Betriebssystems (AUTOSAR_SWS_OS). Das Diagramm spezifiziert die Metamodellstruktur für <code>OsScheduleTable</code> inklusive Sub-Containern, Referenzen und Konfigurationsparametern für Ablaufpläne auf Counter-Basis innerhalb der Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist der Container <code>OsScheduleTable</code> (Multiplizität 0..*).</p>\n<p class=\"fig-p\">Enthaltene Parameter von <code>OsScheduleTable</code>:</p>\n<ul class=\"fig-list\">\n<li><code>OsScheduleTableRepeating</code>: <code>EcucBooleanParamDef</code></li>\n<li><code>OsScheduleTableDuration</code>: <code>EcucIntegerParamDef</code></li>\n</ul>\n<p class=\"fig-p\">Enthaltene Referenzen von <code>OsScheduleTable</code>:</p>\n<ul class=\"fig-list\">\n<li><code>OsScheduleTableCounterRef</code>: <code>EcucReferenceDef</code>, referenziert Zielcontainer <code>OsCounter</code> (0..*).</li>\n</ul>\n<p class=\"fig-p\">Enthaltene Sub-Container (<code>+subContainer</code>) von <code>OsScheduleTable</code>:</p>\n<ul class=\"fig-list\">\n<li><code>OsScheduleTableExpiryPoint</code> (Multiplizität 1..*): Definiert Ablaufzeitpunkte.</li>\n<li>Parameter: <code>OsScheduleTblExpPointOffset</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>).</li>\n<li>Sub-Container <code>OsScheduleTableTaskActivation</code> (0..*): Aktivierung von Tasks.</li>\n<li>Sub-Container <code>OsScheduleTableEventSetting</code> (0..*): Setzen von Events; enthält Referenz <code>OsScheduleTableSetEventRef</code> zu <code>OsEvent</code>.</li>\n<li>Sub-Container <code>OsScheduleTblAdjustableExpPoint</code> (0..1): Parameter <code>OsScheduleTableMaxShorten</code> (<code>min = 0</code>) und <code>OsScheduleTableMaxLengthen</code> (<code>min = 0</code>).</li>\n<li><code>OsScheduleTableAutostart</code> (Multiplizität 0..1): Startverhalten beim OS-Hochlauf.</li>\n<li>Parameter: <code>OsScheduleTableStartValue</code> (<code>EcucIntegerParamDef</code>, 0..1).</li>\n<li>Parameter: <code>OsScheduleTableAutostartType</code> (<code>EcucEnumerationParamDef</code>).</li>\n<li>Referenz: <code>OsScheduleTableAppModeRef</code> (<code>EcucReferenceDef</code>, 1..*), verweist auf Zielcontainer <code>OsAppMode</code>.</li>\n<li><code>OsScheduleTableSync</code> (Multiplizität 0..1): Synchronisationseinstellungen.</li>\n<li>Parameter: <code>OsScheduleTblSyncStrategy</code> (<code>EcucEnumerationParamDef</code>, <code>defaultValue = NONE</code>), Literale <code>NONE</code>, <code>IMPLICIT</code>, <code>EXPLICIT</code>.</li>\n<li>Parameter: <code>OsScheduleTblExplicitPrecision</code> (<code>EcucIntegerParamDef</code>, 0..1, <code>min = 0</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Konfigurations- und Datenstruktur dar; es enthält keine dynamischen Sequenzabläufe, Verhaltensdiagramme oder Zustandsübergänge. Die funktionale Semantik umfasst das zyklische oder einmalige Durchlaufen der Ablaufzeitpunkte (<code>OsScheduleTableExpiryPoint</code>) synchron zu einem <code>OsCounter</code>, das automatische Starten bei Systemstart abhängig von <code>OsAppMode</code> und Startwert sowie optionale Synchronisationsanpassungen über definierte Minimal- und Maximaloffsets (<code>OsScheduleTblAdjustableExpPoint</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Konfigurationswerkzeuge (BSW-Generatoren) und OS-Implementierungen gemäß AUTOSAR OS-Spezifikation. Ein <code>OsScheduleTable</code> benötigt zwingend eine gültige Counter-Referenz sowie mindestens einen Expiry-Point (<code>upperMultiplicity = *</code>, <code>lowerMultiplicity = 1</code>). Die Konfiguration von Synchronisation und Autostart ist jeweils optional (0..1), erfordert bei Vorhandensein jedoch die Einhaltung der Minimalwerte (<code>min = 0</code>) und Referenzen (z. B. mindestens ein AppMode für den Autostart).</p>"}], "trans": [{"from": "FIG-8358d787393ba9ca", "to": "FIG-678078bf25c4870b", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Wegfall des vorangestellten Tabellenkopfs (<code>Scope / Dependency</code>, <code>Included Containers</code>) mit Containerbeschreibungen oberhalb des Klassendiagramms; das UML-Metamodell-Diagramm selbst ist unverändert.</li>\n</ul>"}]};
